export interface FileMetadata {
  name: string;
  content: string;
  size: number;
  modified: string;
}

export async function loadFiles(): Promise<FileMetadata[]> {
  try {
    const files = await readFile('files.json');
    return JSON.parse(files) as FileMetadata[];
  } catch (err) {
    console.error('Failed to load files:', err);
    return [];
  }
}

export async function saveFiles(files: FileMetadata[]): Promise<void> {
  try {
    await writeFile('files.json', JSON.stringify(files, null, 2));
  } catch (err) {
    console.error('Failed to save files:', err);
  }
}

export async function addFile(file: FileMetadata): Promise<void> {
  try {
    const existing = await loadFiles();
    const unique = existing.find(f => f.name === file.name);
    if (unique) {
      unique.content = file.content;
      unique.size = file.size;
      unique.modified = new Date().toISOString();
    } else {
      existing.push(file);
    }
    await saveFiles(existing);
  } catch (err) {
    console.error('Failed to add file:', err);
  }
}

export async function deleteFile(name: string): Promise<void> {
  try {
    const existing = await loadFiles();
    const filtered = existing.filter(f => f.name !== name);
    await saveFiles(filtered);
  } catch (err) {
    console.error('Failed to delete file:', err);
  }
}

export async function searchFiles(query: string): Promise<FileMetadata[]> {
  try {
    const files = await loadFiles();
    return files.filter(f => f.name.includes(query) || f.content.includes(query));
  } catch (err) {
    console.error('Failed to search files:', err);
    return [];
  }
}

import { FileMetadata } from '../data-store/data-store.ts';

export function searchAndFilter(query: string): FileMetadata[] {
  const files = (window as any).loadFiles();
  if (!files) return [];
  return files.filter(f => f.name.includes(query) || f.content.includes(query));
}

export function addFile(file: FileMetadata): void {
  (window as any).addFile(file);
}

export function deleteFile(name: string): void {
  (window as any).deleteFile(name);
}

export function searchFiles(query: string): FileMetadata[] {
  const files = (window as any).loadFiles();
  if (!files) return [];
  return files.filter(f => f.name.includes(query) || f.content.includes(query));
}

