export function render(container: HTMLElement) {
  const title = document.createElement('h1');
  title.textContent = 'File Encryption Tool';
  container.appendChild(title);

  const fileInput = document.createElement('input');
  fileInput.type = 'file';
  fileInput.id = 'fileInput';
  fileInput.accept = '.txt,.json,.js';
  fileInput.addEventListener('change', handleFileChange);
  container.appendChild(fileInput);

  const actionBtn = document.createElement('button');
  actionBtn.textContent = 'Encrypt/Decrypt';
  actionBtn.id = 'actionBtn';
  actionBtn.addEventListener('click', handleAction);
  container.appendChild(actionBtn);

  const outputDiv = document.createElement('div');
  outputDiv.id = 'outputDiv';
  container.appendChild(outputDiv);

  function handleFileChange(event: Event) {
    const target = event.target as HTMLInputElement;
    if (target.files && target.files.length > 0) {
      const file = target.files[0];
      if (file) {
        const reader = new FileReader();
        reader.onload = (e) => {
          if (e.target?.result) {
            const content = e.target.result;
            const lines = (content as string).split('\n').length;
            outputDiv.textContent = `File: ${file.name} · ${lines} lines`;
          }
        };
        reader.readAsText(file);
      }
    }
  }

  function handleAction() {
    const output = document.getElementById('outputDiv');
    if (output) {
      output.textContent = 'Processing...';
    }
    const files = document.getElementById('fileInput');
    if (files && files.files && files.files.length > 0) {
      const file = files.files[0];
      if (file) {
        const reader = new FileReader();
        reader.onload = (e) => {
          if (e.target?.result) {
            const content = e.target.result;
            const lines = (content as string).split('\n').length;
            outputDiv.textContent = `File: ${file.name} · ${lines} lines`;
          }
        };
        reader.readAsText(file);
      }
    }
  }
}
